// CompareSample is the generated lifecycle comparison boundary. Pass stored snapshots and the effective assignment draft; its values are not transformed or compared to the result. Both snapshots, when present, must have the same primary key. This function performs no database work or automatic capture.
func CompareSample(before, after foundryvalue.Optional[Sample], assigned SampleDraft) (SampleChanges, error) {
	before = foundrySampleSnapshot(before)
	after = foundrySampleSnapshot(after)
	var changes SampleChanges
	var err error
	changes.fields.ID, err = lifecycle.CompareModelField(codec.Signed[int](), before, after, assigned.fieldID.IsSet(), func(item Sample) int { return item.ID })
	if err != nil {
		return SampleChanges{}, fmt.Errorf("compare Sample.ID: %w", err)
	}
	if before.IsSet() && after.IsSet() && (changes.fields.ID.Changed() || changes.fields.ID.Assigned()) {
		return SampleChanges{}, foundryfault.New(foundryfault.Invalid, "model change cannot replace or assign its existing primary key")
	}
	changes.fields.Band, err = lifecycle.CompareModelField(codec.Signed[int16](), before, after, assigned.fieldBand.IsSet(), func(item Sample) int16 { return item.Band })
	if err != nil {
		return SampleChanges{}, fmt.Errorf("compare Sample.Band: %w", err)
	}
	changes.fields.Amount, err = lifecycle.CompareModelField(codec.Decimal(), before, after, assigned.fieldAmount.IsSet(), func(item Sample) decimal.Decimal { return item.Amount })
	if err != nil {
		return SampleChanges{}, fmt.Errorf("compare Sample.Amount: %w", err)
	}
	changes.fields.Score, err = lifecycle.CompareModelField(codec.Nullable(codec.Float[float32]()), before, after, assigned.fieldScore.IsSet(), func(item Sample) foundryvalue.Nullable[float32] { return item.Score })
	if err != nil {
		return SampleChanges{}, fmt.Errorf("compare Sample.Score: %w", err)
	}
	changes.fields.At, err = lifecycle.CompareModelField(codec.Time(), before, after, assigned.fieldAt.IsSet(), func(item Sample) time.Time { return item.At })
	if err != nil {
		return SampleChanges{}, fmt.Errorf("compare Sample.At: %w", err)
	}
	changes.fields.Date, err = lifecycle.CompareModelField(codec.Date(), before, after, assigned.fieldDate.IsSet(), func(item Sample) temporal.Date { return item.Date })
	if err != nil {
		return SampleChanges{}, fmt.Errorf("compare Sample.Date: %w", err)
	}
	changes.fields.Local, err = lifecycle.CompareModelField(codec.LocalDateTime(), before, after, assigned.fieldLocal.IsSet(), func(item Sample) temporal.LocalDateTime { return item.Local })
	if err != nil {
		return SampleChanges{}, fmt.Errorf("compare Sample.Local: %w", err)
	}
	changes.fields.Clock, err = lifecycle.CompareModelField(codec.WallTime(), before, after, assigned.fieldClock.IsSet(), func(item Sample) temporal.Time { return item.Clock })
	if err != nil {
		return SampleChanges{}, fmt.Errorf("compare Sample.Clock: %w", err)
	}
	changes.before = before
	changes.after = after
	return changes, nil
}
func foundrySampleSnapshot(snapshot foundryvalue.Optional[Sample]) foundryvalue.Optional[Sample] {
	item, present := snapshot.Get()
	if !present {
		return foundryvalue.Optional[Sample]{}
	}
	return foundryvalue.Set(Sample{
		ID:     item.ID,
		Band:   item.Band,
		Amount: item.Amount,
		Score:  item.Score,
		At:     item.At,
		Date:   item.Date,
		Local:  item.Local,
		Clock:  item.Clock,
	})
}

