// SampleRetrievalHooks declares complete-model read callbacks. Reference a local factory with retrieval=Factory on the model directive. The stored model is a read-only value; getters remain explicit.
type SampleRetrievalHooks struct {
	// Retrieved runs after successful stored hydration and row closure. The executor retains the caller's capability and wrappers; no write transaction is created implicitly. Return an error to stop this read. Nil is skipped.
	Retrieved func(context.Context, database.Executor, Sample) error
}

// SampleRetrievalObserver retains this model's concrete retrieval factory type. Names share the selected database's write/retrieval namespace.
type SampleRetrievalObserver = lifecycle.Observer[Sample, SampleRetrievalHooks]

// NewSampleRetrievalObserver declares a typed retrieval observer without registering or constructing hooks.
func NewSampleRetrievalObserver(observer string) SampleRetrievalObserver {
	return lifecycle.NewRetrievalObserver[Sample, SampleRetrievalHooks](observer)
}

// RegisterSampleRetrievalObserver binds dependency construction to a database module. Its factory runs once per nonempty complete fetch/batch and selected model role; write hydration, DTOs and scalar reads skip it.
func RegisterSampleRetrievalObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer SampleRetrievalObserver, construct func(foundation.Resolver) (func() SampleRetrievalHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (SampleRetrievalHooks) foundryRetrievalHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.RetrievalHooks[Sample], error) {
	factories, err := lifecycle.RetrievalObserverFactories[Sample, SampleRetrievalHooks](observerSet)
	if err != nil {
		return foundryquery.RetrievalHooks[Sample]{}, err
	}
	var allHooks []SampleRetrievalHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Sample]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.RetrievalHooks[Sample]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Sample]{}, err
	}
	return foundryquery.RetrievalHooks[Sample]{Retrieved: func(ctx context.Context, executor database.Executor, item Sample) error {
		for _, hooks := range allHooks {
			if err := ctx.Err(); err != nil {
				return err
			}
			if hooks.Retrieved != nil {
				if err := hooks.Retrieved(ctx, executor, item); err != nil {
					return err
				}
			}
		}
		return ctx.Err()
	}}, nil
}

